 22     /// Takes a string of shell and returns the full list of command args to
 23     /// use with `exec()` to run the shell command.
 24     pub fn derive_exec_args(&self, command: &str, use_login_shell: bool) -> Vec<String> {
 25         match self.shell_type {
 26             ShellType::Zsh | ShellType::Bash | ShellType::Sh => {
 27                 let arg = if use_login_shell { "-lc" } else { "-c" };
 28                 vec![
 29                     self.shell_path.to_string_lossy().to_string(),
 30                     arg.to_string(),
 31                     command.to_string(),
 32                 ]
 33             }
