 35                 let mut args = vec![self.shell_path.to_string_lossy().to_string()];
 36                 if !use_login_shell {
 37                     args.push("-NoProfile".to_string());
 38                 }
 39 
 40                 args.push("-Command".to_string());
 41                 args.push(command.to_string());
 42                 args
 43             }
 44             ShellType::Cmd => {
 45                 let mut args = vec![self.shell_path.to_string_lossy().to_string()];
 46                 args.push("/c".to_string());
 47                 args.push(command.to_string());
 48                 args
 49             }
 50         }
 51     }
 52 }
