 81 /// The shell and startup mode Codex chose for an exec command.
 82 #[derive(Debug, Clone)]
 83 pub(crate) struct ShellInvocation {
 84     pub(crate) shell: Shell,
 85     pub(crate) use_login_shell: bool,
 86 }
 87 
 88 impl ShellInvocation {
 89     pub(crate) fn is_posix_login(&self) -> bool {
 90         self.use_login_shell
 91             && matches!(
 92                 self.shell.shell_type,
 93                 ShellType::Bash | ShellType::Zsh | ShellType::Sh
 94             )
 95     }
 96 
 97     /// Builds launch arguments that try to restore the executor's directories to `PATH`
 98     /// after login startup, so `command` and its children can find them.
 99     ///
100     /// Call this for the POSIX login shell started by Codex when the executor reports
101     /// directories and the user has not explicitly configured `PATH`. The request's login
102     /// mode is unchanged, even if startup makes `PATH` read-only. Returns `None` if no
103     /// directories are reported or the shell or any path cannot use this setup; keep the
104     /// original arguments in that case.
105     pub(crate) fn derive_exec_args_with_path_prepends(
106         &self,
107         command: &str,
108         paths: &[PathUri],
109     ) -> Option<Vec<String>> {
110         if !self.is_posix_login() || paths.is_empty() {
111             return None;
112         }
113         let mut setup = Vec::with_capacity(paths.len());
114         // Prepend backwards so newly added directories retain the executor's order.
115         for path in paths.iter().rev() {
116             if path.infer_path_convention() != Some(PathConvention::Posix) {
117                 return None;
118             }
119             let path = path.inferred_native_path_string();
120             // POSIX PATH has no way to escape a colon inside a single directory.
121             if path.contains(':') {
122                 return None;
123             }
124             let path = shlex::try_quote(&path).ok()?;
125             // Padding `${PATH-}` with colons makes `case` match whole entries, even at the ends;
126             // `-` also handles an unset PATH. Re-export a match so child commands inherit it;
127             // otherwise probe in a subshell: assigning a read-only PATH can exit the login shell
128             // before the user's command runs. `${PATH:+...}` adds `:` only when PATH is nonempty,
129             // so we don't make the shell search the current directory.
130             setup.push(format!(
131                 "case \":${{PATH-}}:\" in *:{path}:*) export PATH ;; \
132                  *) if (export PATH=) 2>/dev/null; then \
133                  export PATH={path}${{PATH:+:\"$PATH\"}}; fi ;; esac"
134             ));
135         }
136         let setup = setup.join("; ");
137         // Keep setup on the first input line so shell diagnostics and $LINENO still refer to
138         // the original script. If the quoted path contains literal newlines, decode only the
139         // setup with eval in the current shell; the trailing `esac` keeps command substitution
140         // from trimming any newlines in the path.
141         let setup = if setup.contains('\n') {
142             let escaped = setup.replace('\\', "\\\\").replace('\n', "\\n");
143             let escaped = shlex::try_quote(&escaped).ok()?;
144             format!("eval \"$(command -p printf '%b' {escaped})\"")
145         } else {
146             setup
147         };
148         let command = format!("{setup}; {command}");
149         Some(self.shell.derive_exec_args(&command, self.use_login_shell))
150     }
151 }
