  6 #[derive(Debug, PartialEq, Eq, Clone, Copy, Serialize, Deserialize)]
  7 pub enum ShellType {
  8     Zsh,
  9     Bash,
 10     PowerShell,
 11     Sh,
 12     Cmd,
 13 }
 14 
 15 impl ShellType {
 16     pub fn name(self) -> &'static str {
 17         match self {
 18             Self::Zsh => "zsh",
 19             Self::Bash => "bash",
 20             Self::PowerShell => "powershell",
 21             Self::Sh => "sh",
 22             Self::Cmd => "cmd",
 23         }
 24     }
 25 }
 26 
 27 #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
 28 pub struct DetectedShell {
 29     pub shell_type: ShellType,
 30     pub shell_path: PathBuf,
 31 }
 32 
 33 impl DetectedShell {
 34     pub fn name(&self) -> &'static str {
 35         self.shell_type.name()
 36     }
 37 }
 38 
 39 pub fn detect_shell_type(shell_path: impl AsRef<std::path::Path>) -> Option<ShellType> {
 40     let shell_path = shell_path.as_ref();
 41     match shell_path.as_os_str().to_str() {
 42         Some("zsh") => Some(ShellType::Zsh),
 43         Some("sh") => Some(ShellType::Sh),
 44         Some("cmd") => Some(ShellType::Cmd),
 45         Some("bash") => Some(ShellType::Bash),
 46         Some("pwsh") => Some(ShellType::PowerShell),
 47         Some("powershell") => Some(ShellType::PowerShell),
 48         _ => {
 49             let shell_name = shell_path.file_stem();
 50             if let Some(shell_name) = shell_name {
 51                 let shell_name_path = std::path::Path::new(shell_name);
 52                 if shell_name_path != shell_path {
 53                     return detect_shell_type(shell_name_path);
 54                 }
 55             }
 56             None
 57         }
 58     }
 59 }
 60 
 61 #[cfg(unix)]
 62 fn get_user_shell_path() -> Option<PathBuf> {
 63     get_user_path(|passwd| passwd.pw_shell)
 64         .map(|path| PathBuf::from(path.to_string_lossy().into_owned()))
 65 }
 66 
 67 /// Read the current account's home directory without consulting the environment.
 68 #[cfg(unix)]
 69 pub fn get_user_home_path() -> Option<PathBuf> {
 70     get_user_path(|passwd| passwd.pw_dir).filter(|path| !path.as_os_str().is_empty())
 71 }
 72 
 73 #[cfg(unix)]
 74 fn get_user_path(field: fn(&libc::passwd) -> *mut libc::c_char) -> Option<PathBuf> {
 75     let uid = unsafe { libc::getuid() };
 76     use std::ffi::CStr;
 77     use std::mem::MaybeUninit;
 78     use std::os::unix::ffi::OsStrExt;
 79     use std::ptr;
 80 
 81     let mut passwd = REDACTED;
 82 
 83     // We cannot use getpwuid here: it returns pointers into libc-managed
 84     // storage, which is not safe to read concurrently on all targets (the musl
