   6 /// Load the interactive configuration used by snapshot capture in a login shell.
   7 /// The caller must already launch the shell with its usual login startup flags.
   8 /// Only Bash and Zsh are supported here; POSIX sh's ENV handling remains in capture.
   9 pub fn shell_startup_script(shell_type: ShellType) -> &'static str {
  10     match shell_type {
  11         ShellType::Zsh => {
  12             r#"if [[ -n "${ZDOTDIR-}" ]]; then
  13   rc="$ZDOTDIR/.zshrc"
  14 elif [[ -n "${HOME-}" ]]; then
  15   rc="$HOME/.zshrc"
  16 else
  17   rc=
  18 fi
  19 [[ -r "$rc" ]] && . "$rc"
  20 "#
  21         }
  22         ShellType::Bash => {
  23             r#"if [ -z "${BASH_ENV-}" ] && [ -n "${HOME-}" ] && [ -r "$HOME/.bashrc" ]; then
  24   . "$HOME/.bashrc"
  25 fi
  26 "#
  27         }
  28         ShellType::Sh | ShellType::PowerShell | ShellType::Cmd => "",
  29     }
  30 }

