 349 pub fn get_shell(shell_type: ShellType) -> Option<DetectedShell> {
 350     match shell_type {
 351         ShellType::Zsh => get_zsh_shell(),
 352         ShellType::Bash => get_bash_shell(),
 353         ShellType::PowerShell => get_powershell_shell(),
 354         ShellType::Sh => get_sh_shell(),
 355         ShellType::Cmd => get_cmd_shell(),
 356     }
 357 }
