 359 pub fn default_user_shell() -> DetectedShell {
 360     default_user_shell_from_path(get_user_shell_path())
 361 }
 362 
 363 pub fn default_user_shell_from_path(user_shell_path: Option<PathBuf>) -> DetectedShell {
 364     if cfg!(windows) {
 365         get_shell(ShellType::PowerShell).unwrap_or_else(ultimate_fallback_shell)
 366     } else {
 367         let user_default_shell = user_shell_path
 368             .and_then(|shell| detect_shell_type(&shell))
 369             .and_then(get_shell);
 370 
 371         let shell_with_fallback = if cfg!(target_os = "macos") {
 372             user_default_shell
 373                 .or_else(|| get_shell(ShellType::Zsh))
 374                 .or_else(|| get_shell(ShellType::Bash))
 375         } else {
 376             user_default_shell
 377                 .or_else(|| get_shell(ShellType::Bash))
 378                 .or_else(|| get_shell(ShellType::Zsh))
 379         };
 380 
 381         shell_with_fallback.unwrap_or_else(ultimate_fallback_shell)
 382     }
 383 }
