111 impl ToolExecutor<ToolInvocation> for ExecCommandHandler {
112     fn tool_name(&self) -> ToolName {
113         ToolName::plain("exec_command")
114     }
116     fn spec(&self) -> ToolSpec {
117         let spec = create_exec_command_tool_with_environment_id(
118             CommandToolOptions {
119                 include_login_parameter: self.options.include_login_parameter,
120                 exec_permission_approvals_enabled: self.options.exec_permission_approvals_enabled,
121             },
122             self.options.include_environment_id,
123             self.options.include_shell_parameter,
124             self.options.include_windows_shell_guidance,
125         );
126         let mut spec = match self.lifetime {
127             ExecCommandLifetime::Interactive => spec,
128             ExecCommandLifetime::OneShot => one_shot_exec_command_spec(spec),
129         };
130         if !self.options.allow_tty
131             && let ToolSpec::Function(spec) = &mut spec
132         {
133             spec.parameters
134                 .properties
135                 .get_or_insert_default()
136                 .remove("tty");
137         }
138         spec
139     }
141     fn supports_parallel_tool_calls(&self) -> bool {
142         true
143     }
145     fn handle<'a>(&'a self, invocation: ToolInvocation) -> codex_tools::ToolExecutorFuture<'a>
146     where
147         ToolInvocation: 'a,
148     {
149         Box::pin(self.handle_call(invocation))
150     }
151 }
153 impl ExecCommandHandler {
154     async fn handle_call(
155         &self,
156         invocation: ToolInvocation,
157     ) -> Result<Box<dyn crate::tools::context::ToolOutput>, FunctionCallError> {
158         let ToolInvocation {
159             session,
160             turn,
161             step_context,
162             cancellation_token,
163             tracker,
164             call_id,
165             payload,
166             ..
167         } = invocation;
169         let arguments = match payload {
170             ToolPayload::Function { arguments } => arguments,
171             _ => {
172                 return Err(FunctionCallError::RespondToModel(
173                     "exec_command handler received unsupported payload".to_string(),
174                 ));
175             }
176         };
178         let manager: &UnifiedExecProcessManager = &session.services.unified_exec_manager;
179         let context = UnifiedExecContext::new(
180             session.clone(),
181             step_context.clone(),
182             cancellation_token,
183             call_id.clone(),
184         );
185         let environment_args: ExecCommandEnvironmentArgs = parse_arguments(&arguments)?;
186         let turn_environment = resolve_tool_environment(
187             &step_context,
188             environment_args.environment_id.as_deref(),
189             "unified exec is unavailable in this session",
190         )?;
191         let native_environment_cwd = turn_environment.cwd().clone();
192         let cwd = environment_args
193             .workdir
194             .as_deref()
195             .filter(|workdir| !workdir.is_empty())
196             .map_or_else(
197                 || Ok(native_environment_cwd.clone()),
198                 |workdir| native_environment_cwd.join(workdir),
199             )
200             .map_err(|err| FunctionCallError::RespondToModel(err.to_string()))?;
201         let environment = Arc::clone(&turn_environment.environment);
202         let fs = environment.get_filesystem();
204         // Remote executors enforce URI-native sandbox policy themselves. Only a host-local
205         // sandbox needs a native cwd for resolving paths nested in the permissions config.
206         let requires_host_native_cwd = !environment.is_remote()
207             && SandboxManager::new().select_initial(
208                 turn_environment.permission_profile(),
209                 SandboxablePreference::Auto,
210                 codex_protocol::sandbox::effective_windows_sandbox_type(
211                     turn_environment.config().windows_sandbox_type,
212                     turn_environment.config().windows_sandbox_level,
213                 ),
214                 turn.network.is_some(),
215             ) != SandboxType::None;
216         // `to_abs_path()` alone cannot identify foreign drive paths: `file:///C:/repo` is
217         // representable as `/C:/repo` on POSIX. Require the inferred convention to match too.
218         let cwd_uses_native_convention =
219             cwd.infer_path_convention() == Some(PathConvention::native());
220         let native_cwd = match cwd.to_abs_path() {
221             Ok(cwd) if cwd_uses_native_convention => Some(cwd),
222             _ if !requires_host_native_cwd => None,
223             Err(err) => return Err(FunctionCallError::RespondToModel(err.to_string())),
224             Ok(_) => {
225                 return Err(FunctionCallError::RespondToModel(format!(
226                     "path URI `{cwd}` does not use the host's native {} path convention",
227                     PathConvention::native()
228                 )));
229             }
230         };
231         let mut args: ExecCommandArgs = match native_cwd.as_ref() {
232             Some(native_cwd) => {
233                 // The base path only resolves paths nested in the permissions config types.
234                 parse_arguments_with_base_path(&arguments, native_cwd)?
235             }
236             None => {
237                 // Foreign executor cwd values cannot seed this host's AbsolutePathBufGuard.
238                 // Sandbox intent and URI-native roots are still sent to the executor.
239                 parse_arguments(&arguments)?
240             }
241         };
242         if args.tty && !session.features().enabled(Feature::UnifiedExecTty) {
243             return Err(FunctionCallError::RespondToModel(
244                 "TTY execution is disabled by config; omit `tty` or set it to false.".to_string(),
245             ));
246         }
247         let sandbox_permissions =
248             resolve_sandbox_permissions(args.sandbox_permissions, args.justification.as_deref())?;
249         let hook_command = args.cmd.clone();
250         maybe_emit_implicit_skill_invocation(
251             session.as_ref(),
252             context.step_context.turn.as_ref(),
253             &hook_command,
254             &cwd,
255             native_cwd.as_ref(),
256             &turn_environment.selection.environment_id,
257         )
258         .await;
259         // Remote environments may use a different OS and must build commands with their native
260         // shell; fall back to the session shell when the environment did not report one.
261         let shell = turn_environment
262             .shell
263             .clone()
264             .map(Arc::new)
265             .unwrap_or_else(|| session.user_shell());
266         // TODO(anp): Resolve requested shells in remote environments instead of restricting
267         // commands to the reported default shell.
268         if environment.is_remote()
269             && let Some(requested_shell) = args.shell.take()
270         {
271             let Some(remote_shell) = turn_environment.shell.as_ref() else {
272                 return Err(FunctionCallError::RespondToModel(format!(
273                     "environment `{}` does not report a shell",
274                     turn_environment.selection.environment_id
275                 )));
276             };
277             if detect_shell_type(Path::new(&requested_shell)) != Some(remote_shell.shell_type) {
278                 return Err(FunctionCallError::RespondToModel(format!(
279                     "environment `{}` only supports `{}`",
280                     turn_environment.selection.environment_id,
281                     remote_shell.name()
282                 )));
283             }
284         }
285         let resolved_command =
286             get_command(&args, shell, turn_environment.config().allow_login_shell)
287                 .map_err(FunctionCallError::RespondToModel)?;
288         let command = resolved_command.command;
289         let ExecCommandArgs {
290             mut tty,
291             yield_time_ms,
292             timeout_ms,
293             max_output_tokens,
294             sandbox_permissions: _,
295             additional_permissions,
296             justification,
297             prefix_rule,
298             ..
299         } = args;
300         let completion_timeout = match self.lifetime {
301             ExecCommandLifetime::Interactive => None,
302             ExecCommandLifetime::OneShot => {
303                 tty = false;
304                 Some(Duration::from_millis(
305                     timeout_ms.unwrap_or(DEFAULT_EXEC_COMMAND_TIMEOUT_MS),
306                 ))
307             }
308         };
310         let exec_permission_approvals_enabled =
311             session.features().enabled(Feature::ExecPermissionApprovals);
312         let requested_additional_permissions = additional_permissions.clone();
313         let sandbox_context =
314             turn_environment.sandbox_context(/*additional_permissions*/ None);
315         let permission_context = file_system_sandbox_policy_context_for_cwd(&sandbox_context, &cwd);
316         let effective_additional_permissions = apply_granted_turn_permissions(
317             &context.step_context,
318             turn_environment,
319             &cwd,
320             sandbox_permissions,
321             additional_permissions,
322         );
323         let additional_permissions_allowed = exec_permission_approvals_enabled
324             || (session.features().enabled(Feature::RequestPermissionsTool)
325                 && effective_additional_permissions.permissions_preapproved);
327         // Sticky turn permissions have already been approved, so they should
328         // continue through the normal exec approval flow for the command.
329         let approval_policy = context.step_context.settings.approval_policy();
330         if effective_additional_permissions
331             .sandbox_permissions
332             .requests_sandbox_override()
333             && !effective_additional_permissions.permissions_preapproved
334             && prompt_is_rejected_by_policy(approval_policy, /*prompt_is_rule*/ false).is_some()
335         {
336             return Err(FunctionCallError::RespondToModel(format!(
337                 "approval policy is {approval_policy:?}; reject command — you cannot ask for escalated permissions if the approval policy is {approval_policy:?}"
338             )));
339         }
341         let normalized_additional_permissions = match implicit_granted_permissions(
342             sandbox_permissions,
343             requested_additional_permissions.as_ref(),
344             &effective_additional_permissions,
345         )
346         .map_or_else(
347             || {
348                 normalize_and_validate_additional_permissions(
349                     additional_permissions_allowed,
350                     approval_policy,
351                     effective_additional_permissions.sandbox_permissions,
352                     effective_additional_permissions.additional_permissions,
353                     effective_additional_permissions.permissions_preapproved,
354                     &permission_context,
355                 )
356             },
357             |permissions| Ok(Some(permissions)),
358         ) {
359             Ok(normalized) => normalized,
360             Err(err) => {
361                 return Err(FunctionCallError::RespondToModel(err));
362             }
363         };
365         let intercepted_patch = intercept_apply_patch(
366             &command,
367             &cwd,
368             fs.as_ref(),
369             turn_environment.clone(),
370             context.session.clone(),
371             Arc::clone(&context.step_context),
372             context.cancellation_token.clone(),
373             Some(&tracker),
374             &context.call_id,
375             "exec_command",
376         )
377         .await;
378         if let Some(output) = intercepted_patch? {
379             return Ok(boxed_tool_output(ExecCommandToolOutput {
380                 event_call_id: String::new(),
381                 chunk_id: String::new(),
382                 wall_time: std::time::Duration::ZERO,
383                 raw_output: output.into_text().into_bytes(),
384                 truncation_policy: step_context.settings.model_info.truncation_policy.into(),
385                 max_output_tokens,
386                 process_id: None,
387                 exit_code: None,
388                 original_token_count: None,
389                 output_omitted_bytes: None,
390                 hook_command: None,
391             }));
392         }
394         emit_unified_exec_tty_metric(&step_context.session_telemetry, tty);
395         crate::tools::lifecycle::notify_command_start(
396             context.session.as_ref(),
397             context.step_context.turn.as_ref(),
398             &context.call_id,
399             &command,
400             &cwd,
401             fs.as_ref(),
402         )
403         .await;
404         // Preparation can be cancelled. Reserve a process only once it is done.
405         let process_id = manager.allocate_process_id().await;
406         let request = ExecCommandRequest {
407             command,
408             shell: resolved_command.shell,
409             hook_command: hook_command.clone(),
410             process_id,
411             yield_time_ms,
412             max_output_tokens,
413             cwd,
414             sandbox_cwd: native_environment_cwd,
415             turn_environment: turn_environment.clone(),
416             network: context.step_context.turn.network.clone(),
417             tty,
418             sandbox_permissions: effective_additional_permissions.sandbox_permissions,
419             additional_permissions: normalized_additional_permissions,
420             additional_permissions_preapproved: effective_additional_permissions
421                 .permissions_preapproved,
422             justification,

