 31 
 32 impl Session {
 33     pub(crate) fn prewarm_shell_snapshots(
 34         self: &Arc<Self>,
 35         step_context: &StepContext,
 36     ) -> Option<AbortOnDropHandle<()>> {
 37         if !self.features().enabled(Feature::ShellSnapshotV2)
 38             || step_context
 39                 .tool_router
 40                 .registered_tool(&ToolName::plain("exec_command"))
 41                 .is_none()
 42         {
 43             return None;
 44         }
 45 
 46         let config = Arc::clone(&step_context.turn.config);
 47         let user_shell = self.user_shell();
 48         if config.active_project.is_untrusted()
 49             || matches!(
 50                 step_context.settings.approval_policy(),
 51                 AskForApproval::UnlessTrusted
 52             )
 53             || step_context.turn.network.is_some()
 54             || config
 55                 .permissions
 56                 .network
 57                 .as_ref()
 58                 .is_some_and(NetworkProxySpec::enabled)
 59         {
 60             return None;
 61         }
 62 
 63         let environments = step_context.environments.clone();
 64         let session = Arc::clone(self);
 65         Some(AbortOnDropHandle::new(tokio::spawn(async move {
 66             for environment in environments.turn_environments() {
 67                 // Remote starts cannot cancel an in-flight capture. Leave them, deferred
 68                 // environments, and managed networking on the normal lazy capture path.
 69                 if environment.environment.is_remote()
 70                     || !environment.shell_snapshot_v2_supported
 71                     || !environment.config().allow_login_shell
 72                     || environment.config().network_policy.is_some()
 73                 {
 74                     continue;
 75                 }
 76 
 77                 let shell = environment.shell.as_ref().unwrap_or(user_shell.as_ref());
 78                 if !matches!(
 79                     shell.shell_type,
 80                     ShellType::Bash | ShellType::Zsh | ShellType::Sh
 81                 ) {
 82                     continue;
 83                 }
 84                 let sandbox = SandboxManager::new()
 85                     .should_sandbox(
 86                         environment.permission_profile(),
 87                         SandboxablePreference::Auto,
 88                         /*has_managed_network_requirements*/ false,
 89                     )
 90                     .then(|| FileSystemSandboxContext {
 91                         sandbox_override: SandboxOverride::NoOverride,
 92                         permissions: environment.permission_profile().clone(),
 93                         cwd: environment.cwd().clone(),
 94                         workspace_roots: environment.workspace_roots().to_vec(),
 95                         user_home_dir: None,
 96                         temporary_directories: None,
 97                         windows_sandbox_selection: executor_windows_sandbox_selection(
 98                             environment.config().windows_sandbox_type,
 99                             environment.config().windows_sandbox_level,
100                             environment.cwd(),
101                         ),
102                         windows_sandbox_proxy_settings_mode: Some(
103                             session.windows_sandbox_proxy_settings_mode,
104                         ),
105                         use_legacy_landlock: environment.config().use_legacy_landlock,
106                     });
107                 let mut env = apply_unified_exec_env(HashMap::new());
108                 env.insert(
109                     CODEX_THREAD_ID_ENV_VAR.to_string(),
110                     session.thread_id().to_string(),
111                 );
112                 inject_session_env(&mut env, session.session_id());
113                 inject_apply_patch_env(&mut env);
114                 inject_permission_profile_env(
115                     &mut env,
116                     environment.active_permission_profile().as_ref(),
117                 );
118                 #[cfg(unix)]
119                 if let Some(path) = environment.shell_environment_policy().r#set.get("PATH") {
120                     env.insert("PATH".to_string(), path.clone());
121                     crate::tools::runtimes::apply_package_path_prepend(
122                         &mut env,
123                         &mut crate::tools::runtimes::RuntimePathPrepends::default(),
124                     );
125                 }
126                 let params = ExecParams {
127                     process_id: format!("shell-snapshot-warmup-{}", Uuid::new_v4()).into(),
128                     metadata: None,
129                     // This capture-only operation never starts the command or routes
130                     // speculative work through tool approvals or exec-policy bypass.
131                     argv: shell.derive_exec_args("", /*use_login_shell*/ true),
132                     cwd: environment.cwd().clone(),
133                     env_policy: Some(exec_env_policy_from_shell_policy(
134                         environment.shell_environment_policy(),
135                     )),
136                     shell_snapshot: Some(ShellSnapshotRequest {
137                         scope_id: format!(
138                             "{}:{}",
139                             session.thread_id(),
140                             environment.selection.environment_id
141                         ),
142                         shell: ShellInfo {
143                             name: shell.name().to_string(),
144                             path: shell.shell_path.to_string_lossy().into_owned(),
145                         },
146                     }),
147                     env,
148                     tty: false,
149                     pipe_stdin: false,
150                     arg0: None,
151                     sandbox,
152                     enforce_managed_network: false,
153                     managed_network: None,
154                     network_proxy: None,
155                 };
156 
157                 let result = environment
158                     .environment
159                     .get_exec_backend()
160                     .prewarm_shell_snapshot(params)
161                     .await;
162                 if let Err(err) = result {
163                     tracing::debug!("failed to warm shell snapshot: {err}");
164                 }
165             }
166         })))
167     }
168 }
169 
170 pub(super) fn shell_snapshot_request(
171     request: &ExecCommandRequest,
172     cwd: &PathUri,
173     context: &UnifiedExecContext,
174 ) -> Option<ShellSnapshotRequest> {
175     if !context.session.features().enabled(Feature::ShellSnapshotV2)
176         || !request.turn_environment.shell_snapshot_v2_supported
177         || request.turn_environment.selection.cwd != *cwd
178         || !request.shell.is_posix_login()
179     {
180         return None;
181     }
182 
183     let shell = &request.shell.shell;
184     Some(ShellSnapshotRequest {
185         scope_id: format!(
186             "{}:{}",
187             context.session.thread_id(),
188             request.turn_environment.selection.environment_id
189         ),
190         shell: ShellInfo {
191             name: shell.name().to_string(),
192             path: shell.shell_path.to_string_lossy().into_owned(),
193         },
194     })
195 }

