 225                 &cwd,
 226                 &shell_environment_policy,
 227                 &shell,
 228                 config.state_db.clone(),
 229                 credential_broker,
 230                 sandbox.as_ref(),
 231             )
 232             .await;
 233             let success_tag = if snapshot.is_ok() { "true" } else { "false" };
 234             let _ = timer.map(|timer| timer.record(&[("success", success_tag)]));
 235             let mut counter_tags = vec![("version", "v1"), ("success", success_tag)];
 236             if let Some(failure_reason) = snapshot.as_ref().err() {
 237                 counter_tags.push(("failure_reason", *failure_reason));
 238             }
 239             config
 240                 .session_telemetry
 241                 .counter("codex.shell_snapshot", /*inc*/ 1, &counter_tags);
 242             snapshot.ok().map(Arc::new)
 243         }
 244         .instrument(snapshot_span)
 245         .await
