 248     #[allow(clippy::too_many_arguments)]
 249     async fn try_create(
 250         codex_home: &AbsolutePathBuf,
 251         session_id: ThreadId,
 252         session_cwd: &AbsolutePathBuf,
 253         shell_environment_policy: &ShellEnvironmentPolicy,
 254         shell: &Shell,
 255         state_db: Option<StateDbHandle>,
 256         credential_broker: Option<SnapshotCredentialBroker>,
 257         sandbox: Option<&ShellSnapshotSandbox>,
 258     ) -> std::result::Result<ShellSnapshotFile, &'static str> {
 259         // File to store the snapshot
 260         let extension = match shell.shell_type {
 261             ShellType::PowerShell => "ps1",
 262             _ => "sh",
 263         };
 264         let nonce = SystemTime::now()
 265             .duration_since(SystemTime::UNIX_EPOCH)
 266             .map(|duration| duration.as_nanos())
 267             .unwrap_or(0);
 268         let path = codex_home
 269             .join(SNAPSHOT_DIR)
 270             .join(format!("{session_id}.{nonce}.{extension}"));
 271         let temp_path = codex_home
 272             .join(SNAPSHOT_DIR)
 273             .join(format!("{session_id}.tmp-{nonce}"));
 274 
 275         // Clean the (unlikely) leaked snapshot files.
 276         let codex_home = codex_home.clone();
 277         let cleanup_session_id = session_id;
 278         tokio::spawn(async move {
 279             if let Err(err) =
 280                 cleanup_stale_snapshots(&codex_home, cleanup_session_id, state_db).await
 281             {
 282                 tracing::warn!("Failed to clean up shell snapshots: {err:?}");
 283             }
 284         });
 285 
 286         // Make the new snapshot.
 287         let credentials = write_shell_snapshot(
 288             shell,
 289             &temp_path,
 290             session_cwd,
 291             shell_environment_policy,
 292             credential_broker.as_ref(),
 293             sandbox,
 294         )
 295         .await
 296         .map_err(|err| {
 297             tracing::warn!(
 298                 "Failed to create shell snapshot for {}: {err:?}",
 299                 shell.name()
 300             );
 301             "write_failed"
 302         })?;
 303         tracing::info!(
 304             "Shell snapshot successfully created: {}",
 305             temp_path.display()
 306         );
 307 
 308         if let Err(err) = validate_snapshot(
 309             shell,
 310             &temp_path,
 311             session_cwd,
 312             credential_broker.as_ref(),
 313             sandbox,
 314         )
 315         .await
 316         {
 317             tracing::error!("Shell snapshot validation failed: {err:?}");
 318             remove_snapshot_file(&temp_path).await;
 319             return Err("validation_failed");
 320         }
 321 
 322         if let Err(err) = fs::rename(&temp_path, &path).await {
 323             tracing::warn!("Failed to finalize shell snapshot: {err:?}");
 324             remove_snapshot_file(&temp_path).await;
 325             return Err("write_failed");
 326         }
 327 
 328         Ok(ShellSnapshotFile {
 329             path,
 330             credentials,

content.content:
