366     #[must_use = "pass private context to the broker when preparing a managed child"]
367     pub(crate) fn restore_credentials(
368         &self,
369         env: &mut HashMap<String, String>,
370         shell_environment_policy: &ShellEnvironmentPolicy,
371     ) -> CredentialBrokerContext {
372         let Some(credentials) = self.credentials.as_ref() else {
373             return CredentialBrokerContext::default();
374         };
375         let mut credential_context = HashMap::new();
376 
377         let mut allowed_snapshot_env = create_env_from_vars(
378             credentials
379                 .credential_env
380                 .iter()
381                 .chain(&credentials.context_env)
382                 .map(|(key, value)| (key.clone(), value.clone())),
383             shell_environment_policy,
384             /*thread_id*/ None,
385         );
386         let explicit_env_overrides = &shell_environment_policy.r#set;
387         for key in &credentials.unset_credential_keys {
388             if !contains_env_key(explicit_env_overrides, key) {
389                 remove_env_value(env, key);
390                 remove_env_value(&mut allowed_snapshot_env, key);
391             }
392         }
393         let mut snapshot_real_credentials = credentials.credential_env.clone();
394         snapshot_real_credentials.insert(
395             CREDENTIAL_BROKER_ACTIVE_ENV_KEY.to_string(),
396             "1".to_string(),
397         );
398         credentials
399             .network_proxy
400             .restore_brokered_credentials(&mut snapshot_real_credentials, &mut []);
401         let mut restored_credential_keys = Vec::new();
402         for (key, value) in &credentials.credential_env {
403             if contains_env_key(explicit_env_overrides, key)
404                 || !contains_env_key(&allowed_snapshot_env, key)
405             {
406                 continue;
407             }
408             if snapshot_real_credentials.get(key) != env_value(env, key) {
409                 insert_env_value(env, key, value);
410                 restored_credential_keys.push(key);
411             }
412         }
413         for (key, value) in &credentials.context_env {
414             let Some(credential_keys) = credentials.context_credential_keys.get(key) else {
415                 continue;
416             };
417             let binding_keys = credentials.binding_context_credential_keys.get(key);
418             let restores_binding_context = binding_keys.is_some_and(|keys| {
419                 keys.iter()
420                     .any(|key| restored_credential_keys.contains(&key))
421             });
422             let needs_binding_context = restores_binding_context
423                 || binding_keys.is_some_and(|keys| {
424                     keys.iter().any(|key| {
425                         env_value(env, key)
426                             .is_some_and(|value| snapshot_real_credentials.get(key) == Some(value))
427                     })
428                 });
429             let allowed_context = contains_env_key(&allowed_snapshot_env, key);
430             let explicit_context = env_value(explicit_env_overrides, key);
431             if explicit_context.is_some() && allowed_context
432                 || !allowed_context && !needs_binding_context
433                 || !credential_keys
434                     .iter()
435                     .any(|credential_key| contains_env_key(&allowed_snapshot_env, credential_key))
436             {
437                 continue;
438             }
439             if restores_binding_context || !contains_env_key(env, key) {
440                 let target = if allowed_context {
441                     &mut *env
442                 } else {
443                     &mut credential_context
444                 };
445                 insert_env_value(target, key, explicit_context.unwrap_or(value));
446             }
447         }
448 
449         for env in [env, &mut credential_context] {
450             let previous = env.insert(
451                 CREDENTIAL_BROKER_ACTIVE_ENV_KEY.to_string(),
452                 "1".to_string(),
453             );
454             credentials
455                 .network_proxy
456                 .restore_brokered_credentials(env, &mut []);
457             if let Some(previous) = previous {
458                 env.insert(CREDENTIAL_BROKER_ACTIVE_ENV_KEY.to_string(), previous);
459             } else {
460                 env.remove(CREDENTIAL_BROKER_ACTIVE_ENV_KEY);
461             }
462         }
463         credential_context.into()
464     }
