576 async fn capture_snapshot(
577     shell: &Shell,
578     cwd: &AbsolutePathBuf,
579     shell_environment_policy: &ShellEnvironmentPolicy,
580     credential_broker: Option<&SnapshotCredentialBroker>,
581     sandbox: Option<&ShellSnapshotSandbox>,
582 ) -> Result<(String, Option<SnapshotCredentials>)> {
583     let broker_config_revision = credential_broker
584         .map(|broker| broker.network_proxy.credential_broker_config_revision())
585         .unwrap_or_default();
586     let shell_type = shell.shell_type;
587     let shell_startup = if credential_broker.is_some_and(|broker| !broker.allow_login_shell) {
588         SnapshotStartup::NonInteractive
589     } else {
590         SnapshotStartup::Interactive
591     };
592     let script = snapshot_capture_script(
593         shell_type,
594         SnapshotCaptureOptions {
595             startup: shell_startup,
596             declarations: true,
597             environment: credential_broker.is_some(),
598         },
599     )
600     .ok_or_else(|| anyhow!("Shell snapshotting is not yet supported for {shell_type:?}"))?;
601     let shell_mode = if credential_broker.is_none_or(|broker| broker.allow_login_shell) {
602         SnapshotShellMode::Login
603     } else {
604         SnapshotShellMode::NonLogin
605     };
606     let raw_snapshot = run_script_with_timeout(
607         shell,
608         &script,
609         SNAPSHOT_TIMEOUT,
610         shell_mode,
611         cwd,
612         credential_broker,
613         sandbox,
614     )
615     .await?;
616     let capture = CapturedSnapshot::parse(shell_type, raw_snapshot.as_bytes())
617         .ok_or_else(|| anyhow!("invalid shell snapshot capture"))?;
618     let Some(credential_broker) = credential_broker else {
619         return Ok((capture.render_script(shell_environment_policy), None));
620     };
621 
622     let original_env = std::str::from_utf8(capture.environment)?
623         .split('\0')
624         .filter_map(|entry| entry.split_once('='))
625         .map(|(key, value)| (key.to_string(), value.to_string()))
626         .collect::<HashMap<_, _>>();
627     // The inherited broker marker survives startup even when its credential variables do not.
628     let mut unset_credential_keys = brokered_credential_marker_env_keys(&original_env)
629         .into_iter()
630         .filter(|key| !contains_env_key(&original_env, key))
631         .collect::<Vec<_>>();
632     let policy = &credential_broker.shell_environment_policy;
633     // Child visibility must not change the trusted destination of an inherited credential.
634     let inherited_env = std::env::vars().collect();
635     let network_config = credential_broker.network_proxy.current_cfg().await?;
636     let inherited_env = network_config
637         .credential_broker_context
638         .with_fallbacks(&inherited_env);
639     let mut restored_env = original_env.clone();
640     credential_broker
641         .network_proxy
642         .restore_brokered_credentials(&mut restored_env, &mut []);
643     let mut discovery_env = restored_env.clone();
644     let provider_environment = credential_broker
645         .network_proxy
646         .credential_broker_environment(&discovery_env);
647     let provider_context_keys = provider_environment.provider_context_keys;
648     replace_provider_context_with_trusted(
649         &mut discovery_env,
650         &inherited_env,
651         provider_context_keys.clone(),
652         &provider_context_keys,
653     );
654     for (key, value) in &policy.r#set {
655         if !contains_env_key(&discovery_env, key)
656             || provider_context_keys
657                 .iter()
658                 .any(|context_key| context_key.eq_ignore_ascii_case(key))
659         {
660             insert_env_value(&mut discovery_env, key, value);
661         }
662     }
663     credential_broker
664         .network_proxy
665         .apply_to_env_for_snapshot(&mut discovery_env);
666     let discovery_metadata = credential_broker
667         .network_proxy
668         .credential_broker_environment(&discovery_env);
669     let brokered_keys = discovery_metadata.credential_keys;
670     let mut env = create_env_from_vars(
671         restored_env
672             .iter()
673             .map(|(key, value)| (key.clone(), value.clone())),
674         policy,
675         /*thread_id*/ None,
676     );
677     let allowed_context_env = create_env_from_vars(
678         provider_context_keys
679             .iter()
680             .map(|key| (key.clone(), String::new())),
681         policy,
682         /*thread_id*/ None,
683     );
684     replace_provider_context_with_trusted(
685         &mut env,
686         &discovery_env,
687         provider_context_keys.clone(),
688         &[],
689     );
690     credential_broker
691         .network_proxy
692         .apply_to_env_for_snapshot(&mut env);
693     let mut snapshot_allowed_env = env.clone();
694     // The live broker regenerates this marker; captured dummies can belong to another scope.
695     snapshot_allowed_env.remove("CODEX_NETWORK_PROXY_BROKERED_CREDENTIALS");
696     for key in &provider_context_keys {
697         if env_value(&original_env, key) != env_value(&env, key) {
698             remove_env_value(&mut snapshot_allowed_env, key);
699         }
700     }
701     for key in &provider_context_keys {
702         if !contains_env_key(&allowed_context_env, key) {
