709     let allowed_brokered_keys = allowed_metadata.credential_keys;
710     let unbrokered_credentials: HashMap<String, String> = env
711         .iter()
712         .filter(|(key, _)| {
713             allowed_metadata.provider_keys.iter().any(|provider_key| {
714                 provider_key == *key || cfg!(windows) && provider_key.eq_ignore_ascii_case(key)
715             }) && !provider_context_keys.iter().any(|context| {
