430             let explicit_context = env_value(explicit_env_overrides, key);
431             if explicit_context.is_some() && allowed_context
432                 || !allowed_context && !needs_binding_context
433                 || !credential_keys
434                     .iter()
435                     .any(|credential_key| contains_env_key(&allowed_snapshot_env, credential_key))
436             {
437                 continue;
438             }
439             if restores_binding_context || !contains_env_key(env, key) {
440                 let target = if allowed_context {
441                     &mut *env
442                 } else {
443                     &mut credential_context
444                 };
445                 insert_env_value(target, key, explicit_context.unwrap_or(value));
446             }
447         }
448 
449         for env in [env, &mut credential_context] {
450             let previous = env.insert(
451                 CREDENTIAL_BROKER_ACTIVE_ENV_KEY.to_string(),
452                 "1".to_string(),
453             );
454             credentials
455                 .network_proxy
456                 .restore_brokered_credentials(env, &mut []);
457             if let Some(previous) = previous {
458                 env.insert(CREDENTIAL_BROKER_ACTIVE_ENV_KEY.to_string(), previous);
459             } else {
460                 env.remove(CREDENTIAL_BROKER_ACTIVE_ENV_KEY);
461             }
462         }
463         credential_context.into()
464     }
