466     pub(crate) fn restore_fail_open_aliases(
467         &self,
468         env: &mut HashMap<String, String>,
469         environment_id: Option<&str>,
470     ) {
471         let Some(credentials) = self.credentials.as_ref() else {
472             return;
473         };
474         if env_value(env, CREDENTIAL_BROKER_ACTIVE_ENV_KEY).is_some_and(|active| active == "1") {
475             for (key, alias) in &credentials.fail_open_aliases {
476                 let has_snapshot_value = alias.dummy_value.as_ref().is_some_and(|dummy| {
477                     env_value(env, key).is_some_and(|value| {
478                         value == dummy
479                             || credentials.network_proxy.child_credential_alias_matches(
480                                 key,
481                                 value,
482                                 dummy,
483                                 environment_id,
484                             )
485                     })
486                 });
487                 if has_snapshot_value {
488                     if !alias.authorized {
489                         remove_env_value(env, key);
490                     }
491                     continue;
492                 }
493                 if env_value(env, key).is_some_and(|value| {
494                     let mut virtualized = value.clone();
495                     !credentials
496                         .network_proxy
497                         .virtualize_brokered_text(&mut virtualized, env)
498                 }) {
499                     remove_env_value(env, key);
500                 }
501             }
502             return;
503         }
504 
505         let policy = &credentials.shell_environment_policy;
506         for (key, alias) in &credentials.fail_open_aliases {
507             if contains_env_key(&policy.r#set, key)
508                 || credentials.unset_credential_keys.contains(key)
509             {
510                 continue;
511             }
512             let has_snapshot_dummy = alias
513                 .dummy_value
514                 .as_ref()
515                 .is_some_and(|dummy| env_value(env, key) == Some(dummy));
516             if has_snapshot_dummy {
517                 if alias.authorized {
518                     insert_env_value(env, key, &alias.value);
519                 } else {
520                     remove_env_value(env, key);
521                 }
522             } else if alias.authorized && !contains_env_key(env, key) {
523                 insert_env_value(env, key, &alias.value);
524             }
525         }
526     }
527 }
