540 async fn write_shell_snapshot(
541     shell: &Shell,
542     output_path: &AbsolutePathBuf,
543     cwd: &AbsolutePathBuf,
544     shell_environment_policy: &ShellEnvironmentPolicy,
545     credential_broker: Option<&SnapshotCredentialBroker>,
546     sandbox: Option<&ShellSnapshotSandbox>,
547 ) -> Result<Option<SnapshotCredentials>> {
548     let shell_type = shell.shell_type;
