550         bail!("Shell snapshot not supported yet for {shell_type:?}");
551     }
552     let (snapshot, credentials) = capture_snapshot(
553         shell,
554         cwd,
555         shell_environment_policy,
556         credential_broker,
557         sandbox,
558     )
559     .await?;
560 
561     if let Some(parent) = output_path.parent() {
562         let parent_display = parent.display();
563         fs::create_dir_all(&parent)
564             .await
565             .with_context(|| format!("Failed to create snapshot parent {parent_display}"))?;
566     }
567 
568     let snapshot_path = output_path.display();
569     fs::write(output_path, snapshot)
570         .await
571         .with_context(|| format!("Failed to write snapshot to {snapshot_path}"))?;
572 
573     Ok(credentials)
574 }
