 35 #[derive(Default)]
 36 pub(super) struct Value {
 37     pub parts: Vec<ValuePart>,
 38 }
 39 
 40 pub(super) enum ValuePart {
 41     Literal(String),
 42     Credential { key: String },
 43 }
 44 
 45 pub(super) enum Export<'a> {
 46     Captured(&'a str),
 47     Assignment {
 48         declaration: &'a str,
 49         value: Value,
 50     },
 51     Array {
 52         prefix: &'a str,
 53         elements: Vec<Value>,
 54         suffix: &'a str,
 55     },
 56     ArrayBinding {
 57         key: &'a str,
 58         declaration: &'a str,
 59         suffix: &'a str,
 60     },
 61 }
 62 
 63 impl Value {
 64     fn render(&self) -> Option<String> {
 65         let mut output = String::new();
 66         for part in &self.parts {
 67             match part {
 68                 ValuePart::Literal(value) => {
 69                     output.push_str(shlex::try_quote(value).ok()?.as_ref())
 70                 }
 71                 ValuePart::Credential { key } => {
 72                     output.push_str(&format!("\"${{{key}-}}\""));
 73                 }
 74             }
 75         }
 76         if output.is_empty() {
 77             output.push_str("''");
 78         }
 79         Some(output)
 80     }
 81 }
 82 
 83 pub(super) fn render(state: &str, aliases: &str, exports: &[Export<'_>]) -> Option<String> {
 84     let mut output = format!("{state}{aliases}");
 85     if !exports.is_empty() {
 86         output.push_str("# exports (native declarations)\n");
 87     }
 88     for export in exports {
 89         match export {
 90             Export::Captured(source) => output.push_str(source),
