 27       ""|[0-9]*|*[!A-Za-z0-9_]*|PWD|OLDPWD) continue ;;
 28     esac
 29     case "${(tP)__codex_snapshot_export_name}" in
 30       *readonly*) continue ;;
 31       *export*) ;;
 32       *) continue ;;
 33     esac
 34     RECORD_START
 35     typeset -xp "$__codex_snapshot_export_name"
 36     RECORD_END
 37   done
