 42             r#"if export -p >/dev/null 2>&1; then
 43 export -p | __codex_snapshot_command awk '
 44 /^(export|declare -x|typeset -x) [A-Za-z_][A-Za-z0-9_]*$/ {
 45   name=$0
 46   sub(/^(export|declare -x|typeset -x) /, "", name)
