  1 //! Serialize prepared snapshot values and apply export-name policy without executing shell code.
  2 //! Native declarations stay unchanged unless the credential stage supplies a replacement.
  3 
  4 use super::capture::CapturedSnapshot;
  5 use codex_protocol::config_types::ShellEnvironmentPolicy;
  6 use codex_protocol::shell_environment::create_env_from_vars;
  7 
  8 impl CapturedSnapshot<'_> {
  9     /// Render native functions, options, and aliases; the executor restores environment separately.
 10     pub fn render_state(&self) -> String {
 11         format!("{}{}", self.state, self.aliases)
 12     }
 13 
 14     /// Persist only exports admitted by the policy. Explicit overrides are supplied
 15     /// by the command environment; never retain their original captured values.
 16     pub fn render_script(&self, policy: &ShellEnvironmentPolicy) -> String {
 17         let allowed = create_env_from_vars(
 18             self.exports
 19                 .iter()
 20                 .map(|export| (export.key.to_string(), String::new())),
 21             policy,
 22             /*thread_id*/ None,
 23         );
 24         let mut script = self.render_state();
 25         script.push_str("# exports (native declarations)\n");
 26         for export in &self.exports {
 27             if allowed.contains_key(export.key) && !policy.r#set.contains_key(export.key) {
 28                 script.push_str(&export.source);
 29             }
 30         }
 31         script
 32     }
