  60 /// Prepends `path_entry` to `PATH`, removing duplicate and empty existing
  61 /// entries.
  62 ///
  63 /// Returns the updated `PATH` value when `env` was changed. Returns `None` when
  64 /// `path_entry` is empty, leaving `env` untouched so an empty entry does not add
  65 /// the current working directory to command lookup.
  66 #[cfg(unix)]
  67 fn prepend_path_entry(env: &mut HashMap<String, String>, path_entry: &str) -> Option<String> {
  68     if path_entry.is_empty() {
  69         None
  70     } else {
  71         let updated_path = match env.get("PATH") {
  72             Some(path) if !path.is_empty() => std::iter::once(path_entry)
  73                 .chain(
  74                     path.split(':')
  75                         .filter(|entry| !entry.is_empty() && *entry != path_entry),
  76                 )
  77                 .collect::<Vec<_>>()
  78                 .join(":"),
  79             _ => path_entry.to_string(),
  80         };
  81         env.insert("PATH".to_string(), updated_path.clone());
  82         Some(updated_path)
  83     }
  84 }
