  86 /// PATH entries owned by Codex runtime setup.
  87 ///
  88 /// These are applied to the live exec environment immediately and replayed after
  89 /// restoring a shell snapshot, unless the user explicitly overrides `PATH`.
  90 #[derive(Debug, Default, Eq, PartialEq)]
  91 pub(crate) struct RuntimePathPrepends {
  92     entries: Vec<String>,
  93 }
  94 
  95 impl RuntimePathPrepends {
  96     #[cfg(unix)]
  97     pub(crate) fn prepend(&mut self, env: &mut HashMap<String, String>, path_entry: &Path) {
  98         let path_entry = path_entry.to_string_lossy().to_string();
  99         if prepend_path_entry(env, &path_entry).is_some() {
 100             self.entries.retain(|entry| entry != &path_entry);
 101             self.entries.push(path_entry);
 102         }
 103     }
 104 
 105     fn shell_exports_after_snapshot(
 106         &self,
 107         explicit_env_overrides: &HashMap<String, String>,
 108     ) -> String {
 109         if explicit_env_overrides.contains_key("PATH") {
 110             return String::new();
 111         }
 112 
 113         self.entries
 114             .iter()
 115             .filter(|entry| !entry.is_empty())
 116             .map(|entry| {
 117                 let entry = shell_single_quote(entry);
 118                 format!(
 119                     "if [ -n \"${{PATH:-}}\" ]; then export PATH='{entry}':\"$PATH\"; else export PATH='{entry}'; fi"
 120                 )

content.content:
120                 )
121             })
122             .collect::<Vec<_>>()
123             .join("\n")
124     }
125 }
