160 fn prepare_powershell_command_for_windows_sandbox_with_fallback(
161     command: &[String],
162     shell_type: Option<&ShellType>,
163     sandbox_requested: bool,
164     windows_sandbox: WindowsSandboxSelection,
165     environment_is_remote: bool,
166     find_fallback: impl FnOnce(&Path) -> Option<codex_shell_command::shell_detect::DetectedShell>,
167 ) -> Vec<String> {
168     if shell_type != Some(&ShellType::PowerShell)
169         || !sandbox_requested
170         || !matches!(
171             windows_sandbox,
172             WindowsSandboxSelection::Elevated | WindowsSandboxSelection::Mxc
173         )
174         || command.is_empty()
175     {
176         return command.to_vec();
177     }
178 
179     let mut command = command.to_vec();
180     if !environment_is_remote && let Some(fallback) = find_fallback(Path::new(&command[0])) {
181         command[0] = fallback.shell_path.to_string_lossy().to_string();
182     }
183 
184     if windows_sandbox != WindowsSandboxSelection::Elevated
185         || command[1..]
186             .iter()
187             .any(|arg| arg.eq_ignore_ascii_case("-NoProfile"))
188     {
189         return command;
190     }
191 
192     // The elevated Windows sandbox runs as a dedicated sandbox account while
193     // HOME/USERPROFILE may still point at the real user profile. Loading
194     // PowerShell profiles in that mixed context is not a valid login shell.
195     command.insert(1, "-NoProfile".to_string());
196     command
197 }
