148     environment_is_remote: bool,
149 ) -> Vec<String> {
150     prepare_powershell_command_for_windows_sandbox_with_fallback(
151         command,
152         shell_type,
153         sandbox_requested,
154         windows_sandbox,
155         environment_is_remote,
156         codex_shell_command::shell_detect::fallback_powershell_shell_for_windows_sandbox,
157     )
158 }
