199 pub(crate) fn prepare_brokered_shell_snapshot_env(
200     env: &mut HashMap<String, String>,
201     shell_snapshot: Option<&AbsolutePathBuf>,
202     shell: &Shell,
203 ) {
204     if shell_snapshot.is_some()
205         && env
206             .get(CREDENTIAL_BROKER_ACTIVE_ENV_KEY)
207             .is_some_and(|active| active == "1")
208     {
209         if !cfg!(windows) {
210             env.retain(|key, _| {
211                 !key.starts_with(SNAPSHOT_BROKERED_VALUE_ENV_PREFIX)
212                     && !key.starts_with(SNAPSHOT_BROKERED_UNSET_ENV_PREFIX)
213             });
214             for key in codex_network_proxy::brokered_credential_value_env_keys(env) {
215                 if is_valid_shell_variable_name(&key)
216                     && let Some(value) = env.get(&key).cloned()
217                 {
218                     env.insert(format!("{SNAPSHOT_BROKERED_VALUE_ENV_PREFIX}{key}"), value);
219                 }
220             }
221             for key in codex_network_proxy::brokered_credential_marker_env_keys(env) {
222                 if !is_valid_shell_variable_name(&key) {
223                     continue;
224                 }
225                 if let Some(value) = env.get(&key).cloned() {
226                     env.entry(format!("{SNAPSHOT_BROKERED_VALUE_ENV_PREFIX}{key}"))
227                         .or_insert(value);
228                 } else {
229                     env.insert(
230                         format!("{SNAPSHOT_BROKERED_UNSET_ENV_PREFIX}{key}"),
231                         "1".to_string(),
232                     );
233                 }
234             }
235         }
236         let bash_env = env.remove("BASH_ENV");
237         if !cfg!(windows)
238             && let Some(bash_env) = bash_env
239             && !bash_env.is_empty()
240         {
241             env.insert(SNAPSHOT_ORIGINAL_BASH_ENV_ENV_KEY.to_string(), bash_env);
242         } else {
243             env.remove(SNAPSHOT_ORIGINAL_BASH_ENV_ENV_KEY);
244         }
245         if shell.shell_type == ShellType::Zsh {
246             if let Some(zdotdir) = env.remove("ZDOTDIR") {
247                 env.insert(SNAPSHOT_ORIGINAL_ZDOTDIR_ENV_KEY.to_string(), zdotdir);
248             } else {
249                 env.remove(SNAPSHOT_ORIGINAL_ZDOTDIR_ENV_KEY);
250             }
251             env.insert("ZDOTDIR".to_string(), "/dev/null".to_string());
252         }
253     }
254 }
