256 /// POSIX-only helper: for commands produced by `Shell::derive_exec_args`
257 /// for Bash/Zsh/sh of the form `[shell_path, "-lc", "<script>"]` or brokered
258 /// `[shell_path, "-c", "<script>"]`, and
259 /// when a snapshot is configured on the session shell, rewrite the argv
260 /// to a single non-login shell that sources the snapshot before running
261 /// the original script:
262 ///
263 ///   shell -lc "<script>"
264 ///   => user_shell -c ". SNAPSHOT (best effort); exec shell -c <script>"
265 ///
266 /// Brokered Bash and Zsh commands targeting the session shell run in that process
267 /// to preserve captured shell functions and avoid asking patched Zsh to exec itself.
268 /// Brokered Zsh wrappers use `-f` so startup files cannot overwrite credentials
269 /// after the proxy has replaced them with dummies.
270 ///
271 /// This wrapper script uses POSIX constructs (`if`, `.`, `exec`) so it can
272 /// be run by Bash/Zsh/sh. On non-matching commands, or when command cwd does
273 /// not match the snapshot cwd, this is a no-op.
274 ///
275 /// `explicit_env_overrides` and `env` are intentionally separate inputs.
276 /// `explicit_env_overrides` contains policy-driven shell env overrides that
277 /// should win after the snapshot is sourced, while `env` is the full live exec
278 /// environment. We need access to both so snapshot restore logic can preserve
279 /// runtime-only vars like `CODEX_THREAD_ID` without pretending they came from
280 /// the explicit override policy.
281 ///
282 /// `runtime_path_prepends` contains Codex-owned PATH entries already applied to
283 /// the live `env`; snapshot wrapping replays them after restoring the snapshot
284 /// PATH unless the user explicitly overrides `PATH`.
285 pub(crate) fn maybe_wrap_shell_lc_with_snapshot(
286     command: &[String],
287     session_shell: &Shell,
288     shell_snapshot: Option<&AbsolutePathBuf>,
289     explicit_env_overrides: &HashMap<String, String>,
290     env: &HashMap<String, String>,
291     runtime_path_prepends: &RuntimePathPrepends,
292 ) -> Vec<String> {
293     if cfg!(windows) {
294         return command.to_vec();
295     }
296 
297     let Some(snapshot) = shell_snapshot else {
298         return command.to_vec();
299     };
300 
301     if !snapshot.exists() {
302         return command.to_vec();
303     }
304 
305     if command.len() < 3 {
306         return command.to_vec();
307     }
308 
309     let brokered = env
310         .get(CREDENTIAL_BROKER_ACTIVE_ENV_KEY)
311         .is_some_and(|active| active == "1");
312     let flag = command[1].as_str();
313     if flag != "-lc" && !(brokered && flag == "-c") {
314         return command.to_vec();
315     }
316 
317     let snapshot_path = snapshot.to_string_lossy();
318     let shell_path = session_shell.shell_path.to_string_lossy();
319     let command_uses_session_zsh =
320         session_shell.shell_type == ShellType::Zsh && command[0] == shell_path.as_ref();
321     let reuse_session_shell = brokered
322         && command[0] == shell_path.as_ref()
323         && matches!(session_shell.shell_type, ShellType::Bash | ShellType::Zsh);
324     let original_shell_is_zsh = command_uses_session_zsh
325         || codex_shell_command::shell_detect::detect_shell_type(&command[0])
326             == Some(ShellType::Zsh);
327     let brokered_zsh_flag = if flag == "-lc" { "-lfc" } else { "-fc" };
328     let original_shell_flag = if brokered && original_shell_is_zsh {
329         brokered_zsh_flag
330     } else {
331         "-c"
332     };
333     let original_shell = shell_single_quote(&command[0]);
334     let snapshot_path = shell_single_quote(snapshot_path.as_ref());
335     let trailing_args = command[3..]
336         .iter()
337         .map(|arg| format!(" '{}'", shell_single_quote(arg)))
338         .collect::<String>();
339     let mut override_env = explicit_env_overrides.clone();
340     for key in [
341         CODEX_SESSION_ID_ENV_VAR,
342         CODEX_THREAD_ID_ENV_VAR,
343         CODEX_TOOL_CALL_ID_ENV_VAR,
344         CODEX_VERSION_ENV_VAR,
345         CODEX_PERMISSION_PROFILE_ENV_VAR,
346         CODEX_APPLY_PATCH_PRESERVE_LINE_ENDINGS_ENV_VAR,
347         PLUGIN_METRICS_OUTPUT_ENV_VAR,
348     ] {
349         if let Some(value) = env.get(key) {
350             override_env.insert(key.to_string(), value.clone());
351         }
352     }
353     // Do not let a snapshot resurrect stale runtime state when it is inactive.
354     let (override_captures, override_exports) = build_override_exports(
355         &override_env,
356         &[
357             CODEX_PERMISSION_PROFILE_ENV_VAR,
358             CODEX_APPLY_PATCH_PRESERVE_LINE_ENDINGS_ENV_VAR,
359             PLUGIN_METRICS_OUTPUT_ENV_VAR,
360             CODEX_TOOL_CALL_ID_ENV_VAR,
361         ],
362     );
363     let (proxy_captures, proxy_exports) = build_proxy_env_exports(env);
364     let (env_captures, replayed_startup_capture, env_exports) = if brokered {
365         let bash_env_key = SNAPSHOT_ORIGINAL_BASH_ENV_ENV_KEY;
366         let posix_env_key = SNAPSHOT_ORIGINAL_POSIX_ENV_ENV_KEY;
367         let startup_env_key =
368             if session_shell.shell_type == ShellType::Sh && env.contains_key(posix_env_key) {
369                 posix_env_key
370             } else {
371                 bash_env_key
372             };
373         let alternate_startup_env_key = if startup_env_key == posix_env_key {
374             bash_env_key
375         } else {
376             posix_env_key
377         };
378         let zdotdir_key = SNAPSHOT_ORIGINAL_ZDOTDIR_ENV_KEY;
379         let expand_env_function = posix_env_path_expansion_function();
380         (
381             format!(
382                 r#"__CODEX_SNAPSHOT_ORIGINAL_ENV_SET="${{ENV+x}}"
383 __CODEX_SNAPSHOT_ORIGINAL_ENV="${{ENV-}}"
384 {expand_env_function}
385 __codex_snapshot_expand_env_with_zdotdir() (
386   if [ -n "${{{zdotdir_key}+x}}" ]; then
387     export ZDOTDIR="${{{zdotdir_key}}}"
388   elif [ -n "${{ZSH_VERSION-}}" ] && [ "${{ZDOTDIR-}}" = /dev/null ]; then
389     unset ZDOTDIR
390   fi
391   __codex_snapshot_expand_env "$1"
392 )
393 __CODEX_SNAPSHOT_PROTECTED_ENV=$(
394   __codex_snapshot_expand_env_with_zdotdir "${{{startup_env_key}-}}"
395 )
396 __CODEX_SNAPSHOT_ALTERNATE_PROTECTED_ENV=$(
397   __codex_snapshot_expand_env_with_zdotdir "${{{alternate_startup_env_key}-}}"
398 )"#
399             ),
400             "__CODEX_SNAPSHOT_REPLAYED_BASH_ENV=\"${BASH_ENV-}\"".to_string(),
401             format!(
402                 r#"__CODEX_SNAPSHOT_CURRENT_ENV=$(
403   __codex_snapshot_expand_env_with_zdotdir "${{ENV-}}"
404 )
405 __CODEX_SNAPSHOT_ORIGINAL_EXPANDED_ENV=$(
406   __codex_snapshot_expand_env_with_zdotdir "$__CODEX_SNAPSHOT_ORIGINAL_ENV"
407 )
408 __CODEX_SNAPSHOT_REPLAYED_PROTECTED_ENV=$(
409   __codex_snapshot_expand_env_with_zdotdir "$__CODEX_SNAPSHOT_REPLAYED_BASH_ENV"
410 )
411 unset -f __codex_snapshot_expand_env __codex_snapshot_expand_env_with_zdotdir
412 __codex_snapshot_env_is_protected() (
413   for __codex_protected_env in \
414     "$__CODEX_SNAPSHOT_PROTECTED_ENV" \
415     "$__CODEX_SNAPSHOT_ALTERNATE_PROTECTED_ENV" \
416     "$__CODEX_SNAPSHOT_REPLAYED_PROTECTED_ENV"; do
417     if [ -n "$__codex_protected_env" ] &&
418       {{ [ "$1" = "$__codex_protected_env" ] ||
419         [ "$1" -ef "$__codex_protected_env" ] 2>/dev/null; }}; then
420       return 0
421     fi
422   done
423   return 1
424 )
425 if __codex_snapshot_env_is_protected "$__CODEX_SNAPSHOT_CURRENT_ENV"; then
426   if [ -n "$__CODEX_SNAPSHOT_ORIGINAL_ENV_SET" ] &&
427     ! __codex_snapshot_env_is_protected "$__CODEX_SNAPSHOT_ORIGINAL_EXPANDED_ENV"; then
428     builtin export ENV="$__CODEX_SNAPSHOT_ORIGINAL_ENV" 2>/dev/null ||
429       command export ENV="$__CODEX_SNAPSHOT_ORIGINAL_ENV" || exit 1
430     [ "${{ENV-}}" = "$__CODEX_SNAPSHOT_ORIGINAL_ENV" ] || exit 1
431   else
432     builtin unset ENV 2>/dev/null || command unset ENV || exit 1
433     [ -z "${{ENV+x}}" ] || exit 1
434   fi
435 fi
436 unset -f __codex_snapshot_env_is_protected
437 unset __CODEX_SNAPSHOT_ORIGINAL_ENV_SET __CODEX_SNAPSHOT_ORIGINAL_ENV \
438   __CODEX_SNAPSHOT_PROTECTED_ENV __CODEX_SNAPSHOT_ALTERNATE_PROTECTED_ENV \
439   __CODEX_SNAPSHOT_REPLAYED_BASH_ENV __CODEX_SNAPSHOT_REPLAYED_PROTECTED_ENV \
440   __CODEX_SNAPSHOT_CURRENT_ENV __CODEX_SNAPSHOT_ORIGINAL_EXPANDED_ENV \
441   {bash_env_key} {posix_env_key}"#
442             ),
443         )
444     } else {
445         (String::new(), String::new(), String::new())
446     };
447     let zsh_startup_exports = if brokered && session_shell.shell_type == ShellType::Zsh {
448         let key = SNAPSHOT_ORIGINAL_ZDOTDIR_ENV_KEY;
449         format!(
450             "if [ -n \"${{{key}+x}}\" ]; then\n  export ZDOTDIR=\"${{{key}}}\"\nelif [ \"${{ZDOTDIR-}}\" = /dev/null ]; then\n  unset ZDOTDIR\nfi\nunset {key}"
451         )
452     } else {
453         String::new()
454     };
455     // Zsh always reads the global zshenv, even with `-f`. Keep private copies of child-visible
456     // dummy values until the command shell has finished startup, then remove the copies.
457     let outer_brokered_credential_exports = if brokered {
458         build_brokered_credential_exports(env, /*remove_copies*/ false)
459     } else {
460         String::new()
461     };
462     let inner_brokered_credential_exports = if brokered {
463         build_brokered_credential_exports(env, /*remove_copies*/ true)
464     } else {
465         String::new()
466     };
467     let original_script = if !inner_brokered_credential_exports.is_empty() {
468         format!("{inner_brokered_credential_exports}\n{}", command[2])
469     } else {
470         command[2].clone()
471     };
472     let runtime_path_prepend_exports =
473         runtime_path_prepends.shell_exports_after_snapshot(explicit_env_overrides);
474     let override_captures = join_shell_blocks([
475         outer_brokered_credential_exports.clone(),
476         override_captures,
477         proxy_captures,
478         env_captures,
479     ]);
480     let override_exports = join_shell_blocks([
481         outer_brokered_credential_exports.clone(),
482         replayed_startup_capture,
483         override_exports,
484         proxy_exports,
485         runtime_path_prepend_exports,
486         env_exports,
487         zsh_startup_exports,
488         outer_brokered_credential_exports,
489     ]);
490     let run_original = if reuse_session_shell {
491         original_script
492     } else {
493         let original_script = shell_single_quote(&original_script);
494         format!("exec '{original_shell}' {original_shell_flag} '{original_script}'{trailing_args}")
495     };
496     let rewritten_script = if override_exports.is_empty() {
497         format!("if . '{snapshot_path}' >/dev/null 2>&1; then :; fi\n\n{run_original}")
498     } else {
499         format!(
500             "{override_captures}\n\nif . '{snapshot_path}' >/dev/null 2>&1; then :; fi\n\n{override_exports}\n\n{run_original}"
501         )
502     };
503 
504     let wrapper_flag = if brokered && session_shell.shell_type == ShellType::Zsh {
505         brokered_zsh_flag
506     } else {
507         "-c"
508     };
509     let mut rewritten = vec![
510         shell_path.to_string(),
511         wrapper_flag.to_string(),
512         rewritten_script,
513     ];
514     if reuse_session_shell {
515         rewritten.extend_from_slice(&command[3..]);
516     }
517     rewritten
518 }
