520 fn build_brokered_credential_exports(env: &HashMap<String, String>, remove_copies: bool) -> String {
521     let mut value_copies = env
522         .keys()
523         .filter_map(|copy_key| {
524             let key = copy_key.strip_prefix(SNAPSHOT_BROKERED_VALUE_ENV_PREFIX)?;
525             is_valid_shell_variable_name(key).then_some((key, copy_key))
526         })
527         .collect::<Vec<_>>();
528     value_copies.sort_unstable();
529     let value_exports = value_copies
530         .into_iter()
531         .map(|(key, copy_key)| {
532             let restore = format!(
533                 "if [ -z \"${{{copy_key}+x}}\" ]; then exit 1; fi\nif [ -n \"${{{key}+x}}\" ] && [ -n \"${{{key}}}\" ] && [ \"${{{key}}}\" != \"${{{copy_key}}}\" ]; then export {key}=\"${{{copy_key}}}\" || exit 1; fi\nif [ -n \"${{{key}+x}}\" ] && [ -n \"${{{key}}}\" ] && [ \"${{{key}}}\" != \"${{{copy_key}}}\" ]; then exit 1; fi"
534             );
535             if remove_copies {
536                 format!("{restore}\nunset {copy_key} || exit 1")
537             } else {
538                 restore
539             }
540         })
541         .collect::<Vec<_>>()
542         .join("\n");
543     let mut unset_markers = env
544         .keys()
545         .filter_map(|marker_key| {
546             let key = marker_key.strip_prefix(SNAPSHOT_BROKERED_UNSET_ENV_PREFIX)?;
547             is_valid_shell_variable_name(key).then_some((key, marker_key))
548         })
549         .collect::<Vec<_>>();
550     unset_markers.sort_unstable();
551     let unset_exports = unset_markers
552         .into_iter()
553         .map(|(key, marker_key)| {
554             let restore = format!(
555                 "if [ -z \"${{{marker_key}+x}}\" ]; then exit 1; fi\nif [ -n \"${{{key}+x}}\" ] && [ -n \"${{{key}}}\" ]; then unset {key} || exit 1; fi\nif [ -n \"${{{key}+x}}\" ] && [ -n \"${{{key}}}\" ]; then exit 1; fi"
556             );
557             if remove_copies {
558                 format!("{restore}\nunset {marker_key} || exit 1")
559             } else {
560                 restore

