256     async fn run(
257         &mut self,
258         req: &UnifiedExecRequest,
259         attempt: &SandboxAttempt<'_>,
260         ctx: &ToolCtx,
261     ) -> Result<UnifiedExecAttempt, ToolError> {
262         let base_command = &req.command;
263         let requested_shell = &req.shell.shell;
264         let windows_sandbox_proxy_settings_mode = ctx.session.windows_sandbox_proxy_settings_mode;
265         let session_shell = ctx.session.user_shell();
266         let environment_shell = req
267             .turn_environment
268             .shell
269             .as_ref()
270             .unwrap_or(session_shell.as_ref());
271         let (file_system_sandbox_policy, _) = attempt.permissions.to_runtime_permissions();
272         let launch_sandbox_permissions = sandbox_permissions_preserving_denied_reads(
273             req.sandbox_permissions,
274             &file_system_sandbox_policy,
275         );
276         let managed_network = attempt.network_proxy(managed_network_for_sandbox_permissions(
277             req.network.as_ref(),
278             launch_sandbox_permissions,
279         ));
280         let environment_is_remote = req.turn_environment.environment.is_remote();
281         let credential_broker_available = !environment_is_remote
282             && req.network.is_some()
283             && ctx
284                 .step_context
285                 .turn
286                 .config
287                 .permissions
288                 .network
289                 .as_ref()
290                 .is_some_and(crate::config::NetworkProxySpec::credential_broker_enabled);
291         let shell = if credential_broker_available {
292             requested_shell
293         } else {
294             environment_shell
295         };
296         let snapshot_metrics =
297             snapshot_metrics::SnapshotMetrics::start(req, &ctx.step_context.turn.config);
298         let shell_snapshot = if environment_is_remote
299             || credential_broker_available
300                 && launch_sandbox_permissions.requires_escalated_permissions()
301         {
302             None
303         } else {
304             // TODO(anp): Make shell snapshot lookup accept PathUri.
305             let native_cwd = req
306                 .cwd
307                 .to_abs_path()
308                 .map_err(|err| ToolError::Rejected(err.to_string()))?;
309             req.turn_environment
310                 .shell_snapshot(
311                     &native_cwd,
312                     base_command,
313                     shell,
314                     &ctx.step_context.turn.config,
315                     Some(ShellSnapshotSandbox::new(
316                         attempt,
317                         managed_network,
318                         &req.turn_environment.selection.environment_id,
319                         req.additional_permissions.as_ref(),
