 96         // iteration times long, so we include this quick fix for now to unblock
 97         // getting the Windows Bazel build running.
 98         if !env_map.keys().any(|k| k.eq_ignore_ascii_case("PATHEXT")) {
 99             env_map.insert("PATHEXT".to_string(), ".COM;.EXE;.BAT;.CMD".to_string());
100         }
101     }
