105 pub fn populate_env<I>(
106     vars: I,
107     policy: &ShellEnvironmentPolicy,
108     thread_id: Option<&str>,
109 ) -> HashMap<String, String>
110 where
111     I: IntoIterator<Item = (String, String)>,
112 {
113     // Step 1 - determine the starting set of variables based on the
114     // `inherit` strategy.
115     let mut env_map: HashMap<String, String> = match policy.inherit {
116         ShellEnvironmentPolicyInherit::All => vars.into_iter().collect(),
117         ShellEnvironmentPolicyInherit::None => HashMap::new(),
118         ShellEnvironmentPolicyInherit::Core => {
119             #[cfg(not(target_os = "windows"))]
120             let core_env_vars = UNIX_CORE_ENV_VARS;
121             #[cfg(target_os = "windows")]
122             let core_env_vars = WINDOWS_CORE_ENV_VARS;
123 
124             vars.into_iter()
125                 .filter(|(k, _)| {
126                     core_env_vars
127                         .iter()
128                         .any(|allowed| allowed.eq_ignore_ascii_case(k))
129                 })
130                 .collect()
131         }
132     };
133 
134     let matches_any = |name: &str, patterns: &[EnvironmentVariablePattern]| -> bool {
135         patterns.iter().any(|pattern| pattern.matches(name))
136     };
137 
138     // Step 2 - Apply the default exclude if not disabled.
139     if !policy.ignore_default_excludes {
140         let default_excludes = vec![
141             EnvironmentVariablePattern::new_case_insensitive("*KEY*"),
142             EnvironmentVariablePattern::new_case_insensitive("*SECRET*"),
143             EnvironmentVariablePattern::new_case_insensitive("*TOKEN*"),
144         ];
145         env_map.retain(|k, _| !matches_any(k, &default_excludes));
146     }
147 
148     // Step 3 - Apply custom excludes.
149     if !policy.exclude.is_empty() {
150         env_map.retain(|k, _| !matches_any(k, &policy.exclude));
151     }
152 
153     // Step 4 - Apply user-provided overrides.
154     for (key, val) in &policy.r#set {
155         #[cfg(windows)]
156         env_map.retain(|existing, _| !existing.eq_ignore_ascii_case(key));
157         env_map.insert(key.clone(), val.clone());
158     }
159 
160     // Step 5 - If include_only is non-empty, keep only the matching vars.
161     if !policy.include_only.is_empty() {
162         env_map.retain(|k, _| matches_any(k, &policy.include_only));
163     }
164 
165     // Step 6 - Populate the thread ID environment variable when provided.
166     if let Some(thread_id) = thread_id {
167         env_map.insert(CODEX_THREAD_ID_ENV_VAR.to_string(), thread_id.to_string());
168     }
169 
170     // Restricted launch context cannot be restored through user-provided shell
171     // environment overrides.
172     env_map.retain(|name, _| !is_non_inheritable_env_var(name));
173 
174     env_map
175 }
