1+169 ///
2+169 /// Handler selection may include internal matcher aliases, but hook stdin keeps
3+169 /// the canonical `tool_name` so audit logs and downstream policy decisions stay
4+169 /// stable. Shell-like tools pass `{ "command": ... }` as `tool_input`; MCP
5+169 /// tools pass their resolved JSON arguments.
6+169 fn command_input_json(request: &PreToolUseRequest) -> Result<String, serde_json::Error> {
7+169     let subagent = SubagentCommandInputFields::from(request.subagent.as_ref());
8+169     serde_json::to_string(&PreToolUseCommandInput {
9+169         session_id: request.session_id.to_string(),
10+169         turn_id: request.turn_id.clone(),
11+169         agent_id: subagent.agent_id,
12+169         agent_type: subagent.agent_type,
13+169         transcript_path: crate::schema::NullableString::from_path(request.transcript_path.clone()),
14+169         cwd: request.cwd.display().to_string(),
15+169         hook_event_name: "PreToolUse".to_string(),
16+169         model: request.model.clone(),
17+169         permission_mode: request.permission_mode.clone(),
18+169         tool_name: request.tool_name.clone(),
19+169         tool_input: request.tool_input.clone(),
20+169         tool_use_id: request.tool_use_id.clone(),
21+169     })
22+169 }
