24+169 fn parse_completed(
25+169     handler: &ConfiguredHandler,
26+169     run_result: HandlerRunResult,
27+169     turn_id: Option<String>,
28+169 ) -> dispatcher::ParsedHandler<PreToolUseHandlerData> {
29+169     let mut entries = Vec::new();
30+169     let mut status = HookRunStatus::Completed;
31+169     let mut should_block = false;
32+169     let mut block_reason = None;
33+169     let mut additional_contexts_for_model = Vec::new();
34+169     let mut updated_input = None;
35+169 
36+169     match run_result.error.as_deref() {
37+169         Some(error) => {
38+169             status = HookRunStatus::Failed;
39+169             entries.push(HookOutputEntry {
40+169                 kind: HookOutputEntryKind::Error,
41+169                 text: error.to_string(),
42+169             });
43+169         }
44+169         None => match run_result.exit_code {
45+169             Some(0) => {
46+169                 let trimmed_stdout = run_result.stdout.trim();
47+169                 if trimmed_stdout.is_empty() {
48+169                 } else if let Some(parsed) = output_parser::parse_pre_tool_use(&run_result.stdout) {
49+169                     if let Some(system_message) = parsed.universal.system_message {
50+169                         entries.push(HookOutputEntry {
51+169                             kind: HookOutputEntryKind::Warning,
52+169                             text: system_message,
53+169                         });
54+169                     }
55+169                     if (!handler.can_apply_control_effects() || parsed.invalid_reason.is_none())
56+169                         && let Some(additional_context) = parsed.additional_context
57+169                     {
58+169                         common::append_additional_context(
59+169                             &mut entries,
60+169                             &mut additional_contexts_for_model,
61+169                             handler,
62+169                             additional_context,
63+169                         );
64+169                     }
65+169                     if handler.can_apply_control_effects() {
66+169                         if let Some(invalid_reason) = parsed.invalid_reason {
67+169                             status = HookRunStatus::Failed;
68+169                             entries.push(HookOutputEntry {
69+169                                 kind: HookOutputEntryKind::Error,
70+169                                 text: invalid_reason,
71+169                             });
72+169                         } else if let Some(reason) = parsed.block_reason {
73+169                             status = HookRunStatus::Blocked;
74+169                             should_block = true;
75+169                             block_reason = Some(reason.clone());
76+169                             entries.push(HookOutputEntry {
77+169                                 kind: HookOutputEntryKind::Feedback,
78+169                                 text: reason,
79+169                             });
80+169                         } else {
81+169                             updated_input = parsed.updated_input;
82+169                         }
83+169                     }
84+169                 } else if output_parser::looks_like_json(&run_result.stdout) {
85+169                     status = HookRunStatus::Failed;
86+169                     entries.push(HookOutputEntry {
87+169                         kind: HookOutputEntryKind::Error,
88+169                         text: "hook returned invalid pre-tool-use JSON output".to_string(),
89+169                     });
90+169                 }
91+169             }
92+169             Some(2) if handler.can_apply_control_effects() => {
93+169                 if let Some(reason) = common::trimmed_non_empty(&run_result.stderr) {
94+169                     status = HookRunStatus::Blocked;
95+169                     should_block = true;
96+169                     block_reason = Some(reason.clone());
97+169                     entries.push(HookOutputEntry {
98+169                         kind: HookOutputEntryKind::Feedback,
99+169                         text: reason,
100+169                     });
101+169                 } else {
102+169                     status = HookRunStatus::Failed;
103+169                     entries.push(HookOutputEntry {
104+169                         kind: HookOutputEntryKind::Error,
105+169                         text: "PreToolUse hook exited with code 2 but did not write a blocking reason to stderr".to_string(),
106+169                     });
107+169                 }
108+169             }
109+169             Some(exit_code) => {
110+169                 status = HookRunStatus::Failed;
111+169                 entries.push(HookOutputEntry {
112+169                     kind: HookOutputEntryKind::Error,
113+169                     text: format!("hook exited with code {exit_code}"),
114+169                 });
115+169             }
116+169             None => {
117+169                 status = HookRunStatus::Failed;
118+169                 entries.push(HookOutputEntry {
119+169                     kind: HookOutputEntryKind::Error,
120+169                     text: "hook exited without a status code".to_string(),
121+169                 });
122+169             }
123+169         },
124+169     }
125+169 
126+169     let completed = HookCompletedEvent {
127+169         turn_id,
128+169         run: dispatcher::completed_summary(handler, &run_result, status, entries),
129+169     };
130+169 
131+169     dispatcher::ParsedHandler {
132+169         completed,
133+169         data: PreToolUseHandlerData {
